const data = $input.first().json;

const total = data.total_deliveries || 0;
const delivered = data.delivered_count || 0;
const failed = data.failed_count || 0;
const successRate = total > 0 ? Math.round((delivered / total) * 100) : 0;
const durationHours = Math.floor((data.shift_duration_min || 0) / 60);
const durationMins = (data.shift_duration_min || 0) % 60;
const avgTimePerStop = total > 0 ? Math.round((data.shift_duration_min || 0) / total) : 0;
const alerts = data.dispatcher_alerts || 0;
const sessions = data.voice_sessions || 0;

// Performance tier
let performanceTier = 'Good';
if (successRate >= 95) performanceTier = 'Excellent';
else if (successRate >= 85) performanceTier = 'Good';
else if (successRate >= 70) performanceTier = 'Needs Improvement';
else performanceTier = 'Poor';

// Flag if alerts are high or success rate is low
const hasIncidents = alerts > 0;
const flagForReview = successRate < 70 || alerts >= 2;

// Check if shift_id is a valid UUID for Supabase schema
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const validShiftId = (data.shift_id && uuidRegex.test(data.shift_id)) ? data.shift_id : null;

// Build executive summary
const summary = [
  `Driver ${data.driver_name} completed their shift on ${data.shift_date}.`,
  `They handled ${total} deliveries: ${delivered} successful, ${failed} failed (${successRate}% success rate).`,
  `Shift duration: ${durationHours}h ${durationMins}m. Average time per stop: ${avgTimePerStop} mins.`,
  alerts > 0 ? `⚠️ ${alerts} dispatcher alert(s) were raised during this shift.` : `✅ No dispatcher alerts raised.`,
  `Voice assistant was used in ${sessions} session(s).`,
  `Overall performance: ${performanceTier}.`
].join(' ');

// Build report object
const report = {
  shift_id: validShiftId,
  raw_shift_id: data.shift_id,
  driver_id: data.driver_id,
  driver_name: data.driver_name,
  shift_date: data.shift_date,
  ended_at: data.ended_at,
  total_deliveries: total,
  delivered_count: delivered,
  failed_count: failed,
  success_rate: successRate,
  shift_duration_min: data.shift_duration_min,
  avg_time_per_stop_min: avgTimePerStop,
  dispatcher_alerts: alerts,
  voice_sessions: sessions,
  performance_tier: performanceTier,
  flag_for_review: flagForReview,
  has_incidents: hasIncidents,
  summary_text: summary,
  operator_email: data.operator_email,
  supabase_url: data.supabase_url,
  supabase_service_key: data.supabase_service_key,
  generated_at: new Date().toISOString()
};

return [{ json: report }];

